import warnings
from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def assertIncomplete(str, symbol='single'):
    """succeed iff str is the start of a valid piece of code"""
    assert compile_command(str, symbol=symbol) == None, ('assertEqual', compile_command(str, symbol=symbol), None)

def _t():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        assertIncomplete("'\\e' + (")
    assert w == [], ('assertEqual', w, [])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import re as _re
import warnings
from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def assertInvalid(str, symbol='single', is_syntax=1):
    """succeed iff str is the start of an invalid piece of code"""
    try:
        compile_command(str, symbol=symbol)
        raise AssertionError('No exception raised for invalid code')
    except SyntaxError:
        assert is_syntax, ('assertTrue', is_syntax)
    except OverflowError:
        assert not is_syntax, ('assertTrue', not is_syntax)

def _t():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        assertInvalid("'\\e' 1")
    assert len(w) == 1, ('assertEqual', len(w), 1)
    assert w[0].category == SyntaxWarning, ('assertEqual', w[0].category, SyntaxWarning)
    assert _re.search('invalid escape sequence', str(w[0].message)), ('assertRegex', str(w[0].message), 'invalid escape sequence')
    assert w[0].filename == '<input>', ('assertEqual', w[0].filename, '<input>')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import re as _re
from textwrap import dedent
from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def assertSyntaxErrorMatches(code, message):
    try:
        compile_command(code, symbol='exec')
    except SyntaxError as _exc:
        assert _re.search(message, str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')

def _t():
    assertSyntaxErrorMatches(dedent('                def foo(x,x):\n                   pass\n            '), "duplicate argument 'x' in function definition")
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
